{
  "root": "root",
  "state": {},
  "elements": {
    "root": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "main_title",
        "intro_text",
        "recommendations_title",
        "cards_stack",
        "quick_actions_title",
        "quick_actions_stack"
      ]
    },
    "main_title": {
      "type": "Text",
      "props": {
        "text": "Recommendations for Your Game Night",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Based on your group's enjoyment of 'Pandemic' and preference for cooperative strategy games that can be learned and played in under two hours, here are three excellent recommendations that avoid the complexity and time commitment of games like 'Gloomhaven'."
      },
      "children": []
    },
    "recommendations_title": {
      "type": "Text",
      "props": {
        "text": "Top Cooperative Games Under Two Hours",
        "variant": "h2"
      },
      "children": []
    },
    "cards_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "card1",
        "card2",
        "card3"
      ]
    },
    "card1": {
      "type": "Card",
      "props": {},
      "children": [
        "card1_stack"
      ]
    },
    "card1_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "card1_header",
        "card1_desc",
        "card1_details",
        "card1_button"
      ]
    },
    "card1_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "card1_icon",
        "card1_title"
      ]
    },
    "card1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000003_01_2_sun.svg"
      },
      "children": []
    },
    "card1_title": {
      "type": "Text",
      "props": {
        "text": "Forbidden Desert",
        "variant": "h3"
      },
      "children": []
    },
    "card1_desc": {
      "type": "Text",
      "props": {
        "text": "A cooperative adventure where you must find a legendary flying machine buried in the ruins of an ancient desert city and escape before you're all buried by the relentless sandstorm or succumb to thirst."
      },
      "children": []
    },
    "card1_details": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "card1_detail1",
        "card1_detail2"
      ]
    },
    "card1_detail1": {
      "type": "Text",
      "props": {
        "text": "• Playtime: 45-60 minutes"
      },
      "children": []
    },
    "card1_detail2": {
      "type": "Text",
      "props": {
        "text": "• Why it's a great fit: Created by the same designer as Pandemic, it offers a familiar feeling of escalating tension and teamwork. The moving board and resource management (water) introduce fresh strategic challenges that are easy to grasp."
      },
      "children": []
    },
    "card1_button": {
      "type": "Button",
      "props": {
        "label": "See on BoardGameGeek"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://boardgamegeek.com/boardgame/136063/forbidden-desert"
          }
        }
      }
    },
    "card2": {
      "type": "Card",
      "props": {},
      "children": [
        "card2_stack"
      ]
    },
    "card2_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "card2_header",
        "card2_desc",
        "card2_details",
        "card2_button"
      ]
    },
    "card2_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "card2_icon",
        "card2_title"
      ]
    },
    "card2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000003_01_3_moon-stars.svg"
      },
      "children": []
    },
    "card2_title": {
      "type": "Text",
      "props": {
        "text": "Horrified",
        "variant": "h3"
      },
      "children": []
    },
    "card2_desc": {
      "type": "Text",
      "props": {
        "text": "Work together to defend a village from classic monsters like Dracula, Frankenstein's Monster, and the Wolfman. Each monster presents a unique challenge, requiring different strategies to defeat."
      },
      "children": []
    },
    "card2_details": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "card2_detail1",
        "card2_detail2"
      ]
    },
    "card2_detail1": {
      "type": "Text",
      "props": {
        "text": "• Playtime: 60 minutes"
      },
      "children": []
    },
    "card2_detail2": {
      "type": "Text",
      "props": {
        "text": "• Why it's a great fit: It's highly thematic and accessible. The variable monster setup provides great replayability, and the rules are straightforward, making it easy to teach new players."
      },
      "children": []
    },
    "card2_button": {
      "type": "Button",
      "props": {
        "label": "See on BoardGameGeek"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://boardgamegeek.com/boardgame/282524/horrified"
          }
        }
      }
    },
    "card3": {
      "type": "Card",
      "props": {},
      "children": [
        "card3_stack"
      ]
    },
    "card3_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "card3_header",
        "card3_desc",
        "card3_details",
        "card3_button"
      ]
    },
    "card3_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "card3_icon",
        "card3_title"
      ]
    },
    "card3_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000003_01_4_rocket.svg"
      },
      "children": []
    },
    "card3_title": {
      "type": "Text",
      "props": {
        "text": "The Crew: The Quest for Planet Nine",
        "variant": "h3"
      },
      "children": []
    },
    "card3_desc": {
      "type": "Text",
      "props": {
        "text": "A cooperative trick-taking card game where players embark on a space adventure. You must work together to complete 50 different missions, but communication is limited, making teamwork and deduction key."
      },
      "children": []
    },
    "card3_details": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "card3_detail1",
        "card3_detail2"
      ]
    },
    "card3_detail1": {
      "type": "Text",
      "props": {
        "text": "• Playtime: 20 minutes"
      },
      "children": []
    },
    "card3_detail2": {
      "type": "Text",
      "props": {
        "text": "• Why it's a great fit: A fresh take on the cooperative genre, blending trick-taking with a campaign. It's very quick, highly replayable, and perfect for groups that enjoy card games."
      },
      "children": []
    },
    "card3_button": {
      "type": "Button",
      "props": {
        "label": "See on BoardGameGeek"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://boardgamegeek.com/boardgame/284083/crew-quest-planet-nine"
          }
        }
      }
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "What's Next?",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "qa_button1",
        "qa_button2"
      ]
    },
    "qa_button1": {
      "type": "Button",
      "props": {
        "label": "Show me more complex games",
        "variant": "borderless"
      },
      "children": []
    },
    "qa_button2": {
      "type": "Button",
      "props": {
        "label": "Find a local game store",
        "variant": "borderless"
      },
      "children": []
    }
  }
}
